const crypto = require('crypto');

function buildDiffUrl(commitSha, filename) {
  const hash = crypto.createHash('sha256').update(filename).digest('hex');
  return `https://github.com/voipmonitor/sniffer/commit/${commitSha}#diff-${hash}`;
}

function extractJsonArray(raw) {
  let cleaned = raw.replace(/```json|```/g, '').trim();
  const start = cleaned.indexOf('[');
  const end = cleaned.lastIndexOf(']');
  if (start !== -1 && end !== -1 && end > start) {
    cleaned = cleaned.substring(start, end + 1);
  }
  return JSON.parse(cleaned);
}

const commitSha = $('GitHub - Fetch Commit Diff').item.json.sha;

const allFileChanges = [];
for (const item of $json.data) {
  const raw = item.choices[0].message.content;
  try {
    const parsed = extractJsonArray(raw);
    if (Array.isArray(parsed)) {
      allFileChanges.push(...parsed);
    } else if (typeof parsed === 'object') {
      for (const [filename, val] of Object.entries(parsed)) {
        const changes = typeof val === 'object' ? (val.changes || JSON.stringify(val)) : val;
        allFileChanges.push({ filename, changes });
      }
    }
  } catch (e) {
    allFileChanges.push({ filename: 'parse-error', changes: raw.substring(0, 300) });
  }
}

allFileChanges.forEach(f => {
  if (f.filename && f.filename !== 'parse-error') {
    f.blob_url = buildDiffUrl(commitSha, f.filename.trim());
  } else {
    f.blob_url = null;
  }
});

return {
  json: {
    commit_sha: commitSha,
    file_changes: allFileChanges,
    combined_notes: allFileChanges.map(f => `${f.filename}: ${f.changes}`).join('\n\n')
  }
};

